const refs = {
  galleryEl: document.querySelector('.gallery'),
};

const createGalleryCard = imegesInfo => {
  return `<li class="gallery-item">
	<a class="gallery-link" href="${imegesInfo.original}">
		<img
			class="gallery-image"
			src="${imegesInfo.preview}"
            data-source="${imegesInfo.original}"
			alt="${imegesInfo.description}"
			/>
	</a>
</li>`;
};

const galleryCards = images.map(img => createGalleryCard(img)).join('');

refs.galleryEl.insertAdjacentHTML('afterbegin', galleryCards);

const galleryLightBox = new SimpleLightbox('.gallery a', {
  captionsData: 'alt',
  captionDelay: 250,
});
